            ctx, reinterpret_cast<const uint8_t *>(sct_data.data()),
            sct_data.size());
      },
      [](SSL_CTX *ctx, CBS *cbs) {
        std::string ocsp_data;
        if (!GetString(&ocsp_data, cbs)) {
